perl << 'PERL'
use strict;
use warnings;
use File::Find;
use File::Basename;

my $REPO = "/bench/repo";
my $MODULE = "github.com/usememos/memos";

my @ENTITIES = qw(
    InstanceSetting IdentityProvider User MemoRelation UserIdentity
    Memo Inbox MemoShare Attachment Reaction UserSetting
    AuthenticationConfigState
);

my %entity_packages; # entity -> { prod => {}, test => {}, all => {} }
for my $e (@ENTITIES) {
    $entity_packages{$e} = { prod => {}, test => {}, all => {} };
}

sub is_outside_store {
    my ($path) = @_;
    my $rel = $path;
    $rel =~ s/^\Q$REPO\E\/?//;
    return 0 if $rel =~ /^store(\/|$)/;
    return 1;
}

sub get_package {
    my ($content) = @_;
    return $1 if $content =~ /^package\s+(\w+)/m;
    return undef;
}

sub get_store_aliases {
    my ($content) = @_;
    my %aliases;
    # Remove comments for simpler parsing
    my $clean = $content;
    $clean =~ s{//.*$}{}gm;

    # Single import
    while ($clean =~ /import\s+"([^"]+)"/g) {
        my $path = $1;
        if ($path eq "$MODULE/store" || $path =~ m{/store$}) {
            $aliases{"store"} = 1;
        }
    }
    # Block import
    while ($clean =~ /import\s*\((.*?)\)/gs) {
        my $block = $1;
        for my $line (split /\n/, $block) {
            $line =~ s/^\s+|\s+$//g;
            next unless $line;
            my ($alias, $path);
            if ($line =~ /^(\w+)\s+"([^"]+)"/) {
                ($alias, $path) = ($1, $2);
            } elsif ($line =~ /^"([^"]+)"/) {
                $path = $1;
                $alias = "store";
            } else { next; }
            if ($path eq "$MODULE/store" || $path =~ m{/store$}) {
                $aliases{$alias} = 1;
            }
        }
    }
    return keys %aliases;
}

sub references_entity {
    my ($content, $entity, $aliases_ref) = @_;
    return 0 unless @$aliases_ref;
    for my $alias (@$aliases_ref) {
        my $q = quotemeta("$alias.$entity");
        return 1 if $content =~ /\b$q\b/;
    }
    return 0;
}

find({
    wanted => sub {
        return unless /\.go$/;
        my $fp = $File::Find::name;
        return unless is_outside_store($fp);
        open my $fh, '<', $fp or return;
        local $/;
        my $content = <$fh>;
        close $fh;

        my $pkg = get_package($content) or return;
        my $dir = $fp;
        $dir =~ s/^\Q$REPO\E\/?//;
        $dir =~ s/\/[^\/]+$//;
        my $pkg_id = "$dir::$pkg";

        my @aliases = get_store_aliases($content);
        my $is_test = ($fp =~ /_test\.go$/) || ($pkg =~ /_test$/);

        for my $entity (@ENTITIES) {
            next unless references_entity($content, $entity, \@aliases);
            $entity_packages{$entity}{all}{$pkg_id} = 1;
            if ($is_test) {
                $entity_packages{$entity}{test}{$pkg_id} = 1;
            } else {
                $entity_packages{$entity}{prod}{$pkg_id} = 1;
            }
        }
    },
    no_chdir => 1,
}, $REPO);

print "=== RANKING (production packages) ===\n";
my @ranked = sort {
    my $ap = scalar keys %{$entity_packages{$a}{prod}};
    my $bp = scalar keys %{$entity_packages{$b}{prod}};
    my $aa = scalar keys %{$entity_packages{$a}{all}};
    my $ba = scalar keys %{$entity_packages{$b}{all}};
    $bp <=> $ap || $ba <=> $aa || $a cmp $b;
} @ENTITIES;

for my $e (@ranked) {
    my $prod = scalar keys %{$entity_packages{$e}{prod}};
    my $all = scalar keys %{$entity_packages{$e}{all}};
    my %test_only;
    for my $k (keys %{$entity_packages{$e}{test}}) {
        $test_only{$k} = 1 unless $entity_packages{$e}{prod}{$k};
    }
    my $test_only = scalar keys %test_only;
    printf "%-30s prod=%3d  test_only=%3d  all=%3d\n", $e, $prod, $test_only, $all;
}

print "\n=== TOP 2 PROD PACKAGE LISTS ===\n";
for my $e (@ranked[0..1]) {
    print "\n--- $e ---\n";
    for my $p (sort keys %{$entity_packages{$e}{prod}}) {
        print "  $p\n";
    }
}
PERL

